export default function build({ THREE, kit, traits, ui, hands }) {
  const root = new THREE.Group();
  root.name = 'Rally Club - two player table tennis';

  const W = 0.38, D = 0.22, TOP = 0.075, R = 0.008;
  const END = 0.205, FLOOR = TOP + R, GRAVITY = 0.65;
  const blue = '#41b9ef', coral = '#ff745d';
  const mat = {
    frame: kit.material('paintedMetal', { color: '#182e39', wear: 0.18 }),
    wood: kit.material('wood', { colors: ['#493022', '#93613d'] }),
    court: kit.material('rubber', { color: '#217d77', roughness: 0.82 }),
    line: kit.material('ceramic', { color: '#f3edcf' }),
    metal: kit.material('brushedMetal', { color: '#96a9ac' }),
    net: kit.material('fabric', { color: '#d5dfd8' }),
    dark: kit.material('rubber', { color: '#122128' }),
    blue: kit.material('rubber', { color: blue }),
    coral: kit.material('rubber', { color: coral }),
    ball: kit.material('plastic', { color: '#fff6d7', roughness: 0.32 }),
    lamp: kit.material('light', { color: '#b4ffe8', glow: 1.7 })
  };
  function mesh(geo, material, x, y, z, parent = root) {
    const m = new THREE.Mesh(geo, material);
    m.position.set(x, y, z);
    parent.add(m);
    return m;
  }
  function box(w, h, d, material, x, y, z, parent = root) {
    return mesh(kit.roundedBox(w, h, d, Math.min(w, h, d) * 0.2),
      material, x, y, z, parent);
  }

  root.add(kit.shadow(0.24, 0.35));
  const decor = new THREE.Group();
  root.add(decor);
  box(0.47, 0.016, 0.30, mat.wood, 0, 0.008, 0, decor);
  box(0.455, 0.005, 0.285, mat.frame, 0, 0.0185, 0, decor);
  box(W, 0.012, D, mat.frame, 0, TOP - 0.006, 0, decor);
  box(W - 0.004, 0.003, D - 0.004, mat.court, 0, TOP - 0.0015, 0, decor);

  // Furniture-grade apron, splayed undercarriage, and chrome levelling feet.
  for (const x of [-0.133, 0.133]) {
    for (const z of [-0.073, 0.073]) {
      box(0.014, 0.043, 0.014, mat.metal, x, 0.043, z, decor);
      mesh(kit.lathe([[0, 0], [0.011, 0], [0.011, 0.004],
        [0.008, 0.006], [0, 0.006]], 24), mat.dark, x, 0.021, z, decor);
    }
    box(0.012, 0.009, 0.16, mat.frame, x, 0.031, 0, decor);
  }
  for (const z of [-0.098, 0.098]) {
    box(0.36, 0.018, 0.009, mat.wood, 0, 0.057, z, decor);
    box(0.27, 0.006, 0.008, mat.metal, 0, 0.039, z * 0.74, decor);
  }
  for (const z of [-D / 2 + 0.004, D / 2 - 0.004])
    box(W - 0.008, 0.0008, 0.002, mat.line, 0, TOP + 0.0004, z, decor);
  for (const x of [-W / 2 + 0.004, W / 2 - 0.004])
    box(0.002, 0.0008, D - 0.008, mat.line, x, TOP + 0.0004, 0, decor);
  box(W - 0.008, 0.0008, 0.0012, mat.line, 0, TOP + 0.0004, 0, decor);

  const bolts = [];
  for (const x of [-0.175, -0.12, 0.12, 0.175])
    for (const z of [-0.103, 0.103]) bolts.push([x, 0.061, z]);
  decor.add(kit.instances(new THREE.SphereGeometry(0.0018, 8, 6), mat.metal, bolts));

  // The net is a real open lattice, not an opaque wall.
  const netBottom = TOP + 0.002, netHeight = 0.026;
  for (const z of [-0.12, 0.12]) {
    box(0.014, 0.008, 0.021, mat.frame, 0, TOP - 0.004, z, decor);
    mesh(new THREE.CylinderGeometry(0.0024, 0.0024, 0.037, 16),
      mat.metal, 0, TOP + 0.012, z, decor);
    mesh(new THREE.SphereGeometry(0.0035, 16, 8),
      mat.line, 0, TOP + 0.032, z, decor);
  }
  const vertical = [], horizontal = [];
  for (let i = 0; i <= 40; i++) vertical.push([0, netBottom + netHeight / 2, -0.115 + i * 0.00575]);
  for (let i = 0; i <= 5; i++) horizontal.push([0, netBottom + i * netHeight / 5, 0]);
  decor.add(kit.instances(kit.roundedBox(0.0006, netHeight, 0.0006, 0.0002), mat.net, vertical));
  decor.add(kit.instances(kit.roundedBox(0.0006, 0.0006, 0.23, 0.0002), mat.net, horizontal));
  box(0.0025, 0.003, 0.235, mat.line, 0, netBottom + netHeight, 0, decor);

  // Little court-side score lamps illuminate with every point.
  const lamps = [];
  for (let side = 0; side < 2; side++) {
    for (let i = 0; i < 7; i++) {
      const x = (side === 0 ? -1 : 1) * (0.035 + i * 0.021);
      box(0.014, 0.003, 0.009, mat.dark, x, 0.023, 0.132, decor);
      const l = box(0.010, 0.002, 0.005, side === 0 ? mat.blue : mat.coral,
        x, 0.025, 0.132);
      lamps.push(l);
    }
  }
  kit.merge(decor);

  const paddles = [];
  for (let i = 0; i < 2; i++) {
    const g = new THREE.Group();
    g.name = i === 0 ? 'Blue - left hand paddle' : 'Coral - right hand paddle';
    g.position.set(i === 0 ? -END : END, 0.128, 0);
    root.add(g);
    const blade = mesh(new THREE.CylinderGeometry(0.040, 0.040, 0.006, 40),
      mat.wood, 0, 0, 0, g);
    blade.rotation.z = Math.PI / 2;
    for (const x of [-0.004, 0.004]) {
      const rubber = mesh(new THREE.CylinderGeometry(0.0385, 0.0385, 0.002, 40),
        i === 0 ? mat.blue : mat.coral, x, 0, 0, g);
      rubber.rotation.z = Math.PI / 2;
    }
    box(0.009, 0.043, 0.015, mat.wood, 0, -0.053, 0, g);
    box(0.010, 0.026, 0.016, mat.dark, 0, -0.057, 0, g);
    const bands = [];
    for (let j = 0; j < 5; j++) bands.push([0, -0.047 - j * 0.004, 0]);
    g.add(kit.instances(kit.roundedBox(0.011, 0.001, 0.017, 0.0004), mat.metal, bands));
    const flash = kit.glow(i === 0 ? blue : coral, 0.10, { opacity: 0.5 });
    flash.visible = false;
    g.add(flash);
    paddles.push({ g, flash, heat: 0, previous: 0, speed: 0 });
  }

  const ball = mesh(new THREE.SphereGeometry(R, 24, 16), mat.ball, -0.17, 0.13, 0);
  ball.name = 'Table tennis ball';
  const ballShadow = kit.shadow(0.012, 0.3);
  ballShadow.position.y = TOP + 0.001;
  root.add(ballShadow);
  const trail = [];
  for (let i = 0; i < 5; i++) {
    const m = mesh(new THREE.SphereGeometry(0.004 * (1 - i * 0.12), 12, 8),
      mat.lamp, ball.position.x, ball.position.y, 0);
    trail.push(m);
  }

  const startPiece = new THREE.Group();
  startPiece.name = 'START - restart match';
  startPiece.position.set(0, 0.031, 0.192);
  root.add(startPiece);
  box(0.09, 0.018, 0.034, mat.frame, 0, 0, 0, startPiece);
  box(0.080, 0.006, 0.027, mat.lamp, 0, 0.012, 0, startPiece);
  const startLabel = kit.card('START', { width: 0.073, color: '#b4ffe8' });
  startLabel.position.set(0, 0.012, 0.020);
  startPiece.add(startLabel);

  let mode = 'demo', paused = false, scores = [0, 0], rally = 0;
  let vx = 0.24, vy = 0, vz = 0, server = 0, wait = 0.8, bounced = false;
  let panel;
  function hud() {
    panel.set('score', scores[0] + ' : ' + scores[1]);
    for (let i = 0; i < 14; i++)
      lamps[i].visible = i % 7 < scores[i < 7 ? 0 : 1];
  }
  function prepare(side) {
    server = side;
    wait = 0.9;
    rally = 0;
    bounced = false;
  }
  function strike(side) {
    const direction = side === 0 ? 1 : -1;
    const speed = Math.min(0.34, 0.235 + rally * 0.008);
    vx = direction * speed;
    const t = (END + 0.11) / speed;
    vy = (FLOOR - ball.position.y + 0.5 * GRAVITY * t * t) / t;
    const p = paddles[side];
    const offset = (ball.position.z - p.g.position.z) / 0.05;
    const target = THREE.MathUtils.clamp(-ball.position.z * 0.35 + offset * 0.065 +
      p.speed * 0.08, -0.089, 0.089);
    vz = (target - ball.position.z) / ((END * 2) / speed);
    bounced = false;
    p.heat = 1;
    p.flash.visible = true;
  }
  function start() {
    scores[0] = scores[1] = 0;
    mode = 'play'; paused = false;
    prepare(0);
    panel.set('state', 'Blue serves. First to 7!', 'neutral');
    panel.set('restart', 'Restart');
    panel.set('pause', 'Pause');
    hud();
  }
  function point(winner, message) {
    if (mode === 'play') {
      scores[winner]++;
      hud();
      paddles[winner].heat = 1;
      if (scores[winner] >= 7) {
        mode = 'over';
        panel.set('state', (winner === 0 ? 'Blue' : 'Coral') + ' wins! Play again?', 'good');
        panel.set('restart', 'Play again');
      } else {
        panel.set('state', message + ' ' + (winner === 0 ? 'Blue' : 'Coral') + ' scores!', 'good');
      }
    }
    prepare(1 - winner);
  }

  panel = kit.panel(ui, {
    width: 0.36, position: [0, 0.335, -0.19], rotationY: 0,
    title: 'Rally Club',
    items: [
      { text: 'Left hand = blue, right = coral. Slide forward/back to rally.' },
      { stat: '0 : 0', label: 'BLUE                 FIRST TO 7                 CORAL', id: 'score' },
      { status: 'Press START. Keep the ball on the table!', tone: 'neutral', id: 'state' },
      { buttons: [
        { label: 'Start', id: 'restart', onPress: start },
        { label: 'Pause', id: 'pause', onPress() {
          if (mode !== 'play') return;
          paused = !paused;
          panel.set('pause', paused ? 'Resume' : 'Pause');
          panel.set('state', paused ? 'Paused' : 'Rally on!', 'neutral');
        } }
      ] }
    ]
  });
  root.add(panel.object3D);
  traits(startPiece, { onPress: start });
  hud();

  return {
    root,
    update(time, delta) {
      const dt = Math.min(delta, 0.05);
      const demo = mode !== 'play';
      for (let i = 0; i < 2; i++) {
        const p = paddles[i];
        const hand = i === 0 ? hands.left : hands.right;
        p.previous = p.g.position.z;
        if (demo && !paused) {
          const target = ball.position.z + Math.sin(time * 1.5 + i) * 0.006;
          p.g.position.z += (target - p.g.position.z) * Math.min(1, dt * 9);
        } else if (hand && hand.tracked && !paused) {
          const target = THREE.MathUtils.clamp(hand.tip.z, -0.104, 0.104);
          p.g.position.z += (target - p.g.position.z) * (1 - Math.exp(-18 * dt));
        }
        p.speed = dt > 0 ? (p.g.position.z - p.previous) / dt : 0;
        p.heat = Math.max(0, p.heat - dt * 3.5);
        p.flash.visible = p.heat > 0;
        p.flash.scale.setScalar(0.75 + p.heat * 0.5);
      }
      startPiece.scale.y = 1 + Math.sin(time * 3) * (mode === 'demo' ? 0.08 : 0.015);
      if (paused) return;

      if (wait > 0) {
        wait -= dt;
        ball.position.set(server === 0 ? -END : END, 0.128, paddles[server].g.position.z);
        if (wait <= 0) strike(server);
      } else {
        // Substeps prevent a slow frame from skipping a paddle or the net.
        const step = dt / 3;
        for (let j = 0; j < 3 && wait <= 0; j++) {
          const oldX = ball.position.x;
          const oldY = ball.position.y;
          ball.position.x += vx * step;
          ball.position.z += vz * step;
          ball.position.y += vy * step - 0.5 * GRAVITY * step * step;
          vy -= GRAVITY * step;

          if (oldX * ball.position.x < 0 &&
              ball.position.y - R < netBottom + netHeight &&
              Math.abs(ball.position.z) < 0.12) {
            point(vx > 0 ? 0 : 1, 'Net!');
            break;
          }
          if (ball.position.y <= FLOOR && oldY >= FLOOR &&
              Math.abs(ball.position.x) < W / 2 &&
              Math.abs(ball.position.z) < D / 2) {
            if (bounced) {
              point(vx > 0 ? 0 : 1, 'Double bounce!');
              break;
            }
            ball.position.y = FLOOR;
            vy = Math.abs(vy) * 0.55;
            bounced = true;
          }
          const side = vx > 0 ? 1 : 0;
          const reached = side === 1 ? ball.position.x >= END : ball.position.x <= -END;
          if (reached) {
            const paddle = paddles[side];
            if (Math.abs(ball.position.z - paddle.g.position.z) < 0.050 &&
                Math.abs(ball.position.y - 0.128) < 0.059 && bounced) {
              ball.position.x = side === 1 ? END - 0.001 : -END + 0.001;
              rally++;
              strike(side);
              if (mode === 'play') panel.set('state', 'Hit! Rally ' + rally, 'good');
            } else {
              point(1 - side, 'Miss!');
              break;
            }
          }
          if (ball.position.y < 0.025 || Math.abs(ball.position.z) > 0.155) {
            point(vx > 0 ? 1 : 0, 'Out!');
            break;
          }
        }
      }
      ball.rotation.z += dt * 5;
      ballShadow.position.x = ball.position.x;
      ballShadow.position.z = ball.position.z;
      ballShadow.scale.setScalar(1 + Math.max(0, ball.position.y - FLOOR) * 3);
      for (let i = trail.length - 1; i >= 0; i--) {
        const target = i === 0 ? ball.position : trail[i - 1].position;
        trail[i].position.lerp(target, Math.min(1, dt * 24));
        trail[i].visible = wait <= 0;
      }
    }
  };
}
